function dryden = build_dryden_filter(V, Lg, sigmaW, tau)
%BUILD_DRYDEN_FILTER Build vertical Dryden turbulence and gust-rate dynamics.
%
% Lg is the turbulence scale length used by the ZAERO CGUST card. Before
% the optional numerical LPF is applied, the filter shape corresponds to
%
%   Phi(omega) = sigmaW^2*(Lg/V) *
%                (1 + 3*(omega*Lg/V)^2) /
%                (1 +   (omega*Lg/V)^2)^2.
%
% The physical gust velocity is generated by the second-order filter
%
%   Wg(s)       b1*s + b0
%   ----- = ------------------- .
%   Ug(s)   s^2 + a1*s + a0
%
% Differentiating Wg directly produces a white-noise feedthrough.  A
% first-order LPF is therefore applied only to the gust-rate output:
%
%   tau*wdot_g_filtered_dot + wdot_g_filtered = d(w_g)/dt.
%
% The wind spectrum itself is not changed by this numerical LPF.  The
% returned output matrix maps the states to [w_g; wdot_g_filtered].

arguments
    V (1,1) double {mustBePositive}
    Lg (1,1) double {mustBePositive}
    sigmaW (1,1) double {mustBeNonnegative}
    tau (1,1) double {mustBePositive}
end

a1 = 2*V/Lg;
a0 = (V/Lg)^2;
b1 = sigmaW*V*sqrt(3/(pi*Lg));
b0 = sigmaW*V^2/(sqrt(pi)*Lg^(3/2));

% Second-order Dryden realization for the physical gust velocity.
Af = [0, 1; -a0, -a1];
Bf = [0; 1];
Cf = [b0, b1];

% The third state is the low-pass-filtered gust rate.  Including Cf*Bf in
% Bw moves the otherwise direct white-noise term into this filter state, so
% both returned outputs have zero direct feedthrough.
Aw = [ ...
    Af,                    zeros(2,1); ...
    (Cf*Af)/tau,           -1/tau];
Bw = [Bf; (Cf*Bf)/tau];

Cwg = [Cf, 0];
Cwdot = [0, 0, 1];
Cw = [Cwg; Cwdot];
Dw = zeros(2,1);

if any(real(eig(Aw)) >= 0)
    error('Dryden shaping filter is not asymptotically stable.');
end

% Expected covariance for continuous unit-intensity white-noise input.
stateCovariance = lyap(Aw, Bw*Bw.');
unitNoiseRmsWg = sqrt(max(Cwg*stateCovariance*Cwg.', 0));
if sigmaW == 0
    inputNoiseScale = 0;
elseif unitNoiseRmsWg <= 0
    error('Could not normalize the Dryden filter to the requested sigma_w.');
else
    inputNoiseScale = sigmaW/unitNoiseRmsWg;
end

dryden = struct();
dryden.A = Aw;
dryden.B = Bw;
dryden.C = Cw;
dryden.D = Dw;
dryden.a0 = a0;
dryden.a1 = a1;
dryden.b0 = b0;
dryden.b1 = b1;
dryden.V = V;
dryden.Lg = Lg;
dryden.sigmaW = sigmaW;
dryden.tau = tau;
dryden.stateCovariance = stateCovariance;
dryden.unitNoiseRmsWg = unitNoiseRmsWg;
dryden.inputNoiseScale = inputNoiseScale;
dryden.expectedRmsWg = inputNoiseScale*unitNoiseRmsWg;
dryden.coreA = Af;
dryden.coreB = Bf;
dryden.coreC = Cf;

end
